    private static func loadLexicon() -> [String: [String]] {
        let possibleUrls: [URL?] = [
            Bundle.main.url(forResource: "lexicon", withExtension: "json"),
            Bundle(for: PinyinEngine.self).url(forResource: "lexicon", withExtension: "json"),
            URL(fileURLWithPath: "/Users/chenxu/IdeaProjects/AetherKey/Resources/lexicon.json")
        ]
        
        var loaded: [String: [String]] = [:]
        for case let url? in possibleUrls {
            if let data = try? Data(contentsOf: url),
               let dict = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: [String]] {
                loaded = dict
                break
            }
        }
        
        // Merge builtinCorePhrases so essential daily words are guaranteed to be present at top rank
        for (key, words) in builtinCorePhrases {
            if var existing = loaded[key] {
                for w in words.reversed() {
                    existing.removeAll(where: { $0 == w })
                    existing.insert(w, at: 0)
                }
                loaded[key] = existing
            } else {
                loaded[key] = words
            }
        }
        return loaded
    }
}

/// Represents a segmented syllable or partial syllable token with its raw buffer offset.
public struct SyllableToken: Sendable, Equatable {
    public let text: String
    public let rawEndOffset: Int
    public let isComplete: Bool
}

/// Fast Chinese Pinyin segmentation and candidate generation engine for AetherKey.
/// Supports dynamic syllable segmentation, DP sentence composition, incremental prefix matching,
/// Jianpin abbreviations, fuzzy pinyin, user frequency learning, and partial prefix selection.
public final class PinyinEngine: Sendable {
    public static let shared = PinyinEngine()
    
    /// All valid syllable prefixes (length 1..5) for fast incremental typing detection
    private let validPrefixes: Set<String>
    
    public init() {
        var prefixes = Set<String>()
        for s in PinyinLexicon.allSyllables {
            let chars = Array(s)
            for len in 1..<chars.count {
                prefixes.insert(String(chars[0..<len]))
            }
        }
        for initKey in PinyinLexicon.initialExpansions.keys {
            prefixes.insert(initKey)
        }
        self.validPrefixes = prefixes
    }
    
    /// Pre-warms lexicon in background so the first keystroke has zero I/O latency.
    public func preload() {
        _ = PinyinLexicon.commonPhrases.count
        _ = PinyinLexicon.syllablesChars.count
        _ = UserLexicon.shared.learnedEntryCount
    }
    
    /// Dynamic programming based maximal syllable segmenter (compatibility API).
    public func segment(rawInput: String) -> [String] {
        let tokens = segmentTokens(rawInput: rawInput)
        return tokens.map(\.text)
    }
    
    /// Formats raw pinyin input with syllable separator apostrophes (e.g. "nihao" -> "ni'hao").
    public func formatSegmentedPinyin(rawInput: String) -> String {
        let tokens = segmentTokens(rawInput: rawInput)
        guard !tokens.isEmpty else { return rawInput }
        return tokens.map(\.text).joined(separator: "'")
    }
    
    /// Tokenizes raw input into complete syllables and/or trailing/initial prefixes, preserving raw offsets.
    public func segmentTokens(rawInput: String) -> [SyllableToken] {
        let lower = rawInput.lowercased().replacingOccurrences(of: "ü", with: "v")
        let rawChars = Array(lower)
        let totalLen = rawChars.count
        guard totalLen > 0 else { return [] }
        
        // Split into apostrophe-delimited segments while tracking exact offsets in rawInput
        var chunks: [(text: String, rawStart: Int, rawEndAfterApostrophe: Int)] = []
        var chunkStart = 0
        var i = 0
        while i < totalLen {
            if rawChars[i] == "'" {
                if i > chunkStart {
                    let sub = String(rawChars[chunkStart..<i])
                    var endIdx = i
                    while endIdx < totalLen && rawChars[endIdx] == "'" {
                        endIdx += 1
                    }
                    chunks.append((sub, chunkStart, endIdx))
                    chunkStart = endIdx
                    i = endIdx
                    continue
                } else {
                    chunkStart = i + 1
                }
            }
            i += 1
        }
        if chunkStart < totalLen {
            let sub = String(rawChars[chunkStart..<totalLen])
            chunks.append((sub, chunkStart, totalLen))
        }
        
        var allTokens: [SyllableToken] = []
        for chunk in chunks {
            let subTokens = segmentChunk(
                text: chunk.text,
                rawStart: chunk.rawStart,
                chunkFinalEnd: chunk.rawEndAfterApostrophe
            )
            allTokens.append(contentsOf: subTokens)
        }
        return allTokens
    }
    
    private func segmentChunk(text: String, rawStart: Int, chunkFinalEnd: Int) -> [SyllableToken] {
        var normalized = text
        if normalized.contains("gn") && !PinyinLexicon.allSyllables.contains(normalized) {
            normalized = normalized.replacingOccurrences(of: "gn", with: "ng")
        }
        
        let chars = Array(normalized)
        let n = chars.count
        guard n > 0 else { return [] }
        
        struct DPState {
            let tokens: [SyllableToken]
            let cost: Int
        }
        
        var dp: [DPState?] = Array(repeating: nil, count: n + 1)
        dp[0] = DPState(tokens: [], cost: 0)
        
        for idx in 0..<n {
            guard let cur = dp[idx] else { continue }
            let maxLen = min(6, n - idx)
            for len in 1...maxLen {
                let sub = String(chars[idx..<(idx + len)])
                let isEndOfChunk = (idx + len == n)
                let rawEnd = isEndOfChunk ? chunkFinalEnd : (rawStart + idx + len)
                
                if PinyinLexicon.allSyllables.contains(sub) {
                    // Valid full syllable: low cost (10 per syllable, slight bonus for longer syllables)
                    // Prefer splitting "zhansan" as "zhan"+"san", "xian" as "xian"
                    let stepCost = 10
                    let newCost = cur.cost + stepCost
                    if dp[idx + len] == nil || newCost < dp[idx + len]!.cost {
                        let tok = SyllableToken(text: sub, rawEndOffset: rawEnd, isComplete: true)
                        dp[idx + len] = DPState(tokens: cur.tokens + [tok], cost: newCost)
                    }
                } else if validPrefixes.contains(sub) && len <= 5 {
                    // Partial prefix or initial consonant (e.g. "zh", "ch", "sh", "n", "h", "zho", "zhon")
                    // Higher cost so full syllables are always preferred when valid
                    let stepCost = (sub == "zh" || sub == "ch" || sub == "sh") ? 26 : (len == 1 ? 28 : 30)
                    let newCost = cur.cost + stepCost
                    if dp[idx + len] == nil || newCost < dp[idx + len]!.cost {
                        let tok = SyllableToken(text: sub, rawEndOffset: rawEnd, isComplete: false)
                        dp[idx + len] = DPState(tokens: cur.tokens + [tok], cost: newCost)
                    }
                }
            }
        }
        
        return dp[n]?.tokens ?? []
    }
    
    /// Expands an incomplete syllable prefix or initial consonant to top full syllables.
    private func expandPrefix(_ prefix: String) -> [String] {
        var results: [String] = []
        var seen = Set<String>()
        
        if let mapped = PinyinLexicon.initialExpansions[prefix] {
            for s in mapped where !seen.contains(s) {
                seen.insert(s)
                results.append(s)
            }
        }
        
        if PinyinLexicon.allSyllables.contains(prefix) && !seen.contains(prefix) {
            seen.insert(prefix)
            results.insert(prefix, at: 0)
        }
        
        // Also find all syllables starting with prefix
        for s in PinyinLexicon.allSyllables.sorted() where s.hasPrefix(prefix) && !seen.contains(s) {
            seen.insert(s)
            results.append(s)
        }
        return results
    }
    
    /// Generates fuzzy pinyin variants for a syllable when fuzzy pinyin is enabled.
    private func fuzzySyllableVariants(_ s: String) -> [String] {
        guard AetherSettings.shared.isFuzzyPinyinEnabled else { return [] }
        var variants: [String] = []
        
        // Initial consonant fuzzy: z <-> zh, c <-> ch, s <-> sh
        var initialVariants: [String] = [s]
        if s.hasPrefix("zh") {
            initialVariants.append("z" + s.dropFirst(2))
        } else if s.hasPrefix("ch") {
            initialVariants.append("c" + s.dropFirst(2))
        } else if s.hasPrefix("sh") {
            initialVariants.append("s" + s.dropFirst(2))
        } else if s.hasPrefix("z") {
            initialVariants.append("zh" + s.dropFirst(1))
        } else if s.hasPrefix("c") {
            initialVariants.append("ch" + s.dropFirst(1))
        } else if s.hasPrefix("s") {
            initialVariants.append("sh" + s.dropFirst(1))
        }
        
        // Final nasal fuzzy: an <-> ang, en <-> eng, in <-> ing
        for v in initialVariants {
            if v != s && PinyinLexicon.allSyllables.contains(v) {
                variants.append(v)
            }
            if v.hasSuffix("ang") {
                let alt = String(v.dropLast(1))
                if PinyinLexicon.allSyllables.contains(alt) { variants.append(alt) }
            } else if v.hasSuffix("an") {
                let alt = v + "g"
                if PinyinLexicon.allSyllables.contains(alt) { variants.append(alt) }
            } else if v.hasSuffix("eng") {
                let alt = String(v.dropLast(1))
                if PinyinLexicon.allSyllables.contains(alt) { variants.append(alt) }
            } else if v.hasSuffix("en") {
                let alt = v + "g"
                if PinyinLexicon.allSyllables.contains(alt) { variants.append(alt) }
            } else if v.hasSuffix("ing") {
                let alt = String(v.dropLast(1))
                if PinyinLexicon.allSyllables.contains(alt) { variants.append(alt) }
            } else if v.hasSuffix("in") {
                let alt = v + "g"
                if PinyinLexicon.allSyllables.contains(alt) { variants.append(alt) }
            }
        }
        return variants
    }
    
    /// Dynamic Programming Sentence Composer over segmented syllable tokens.
    /// Assembles multi-phrase sentences like "woxiangchifan" -> "我想吃饭", "jintiantianqizenmeyang" -> "今天天气怎么样".
    private func composeSentence(tokens: [SyllableToken]) -> String? {
        let m = tokens.count
        guard m >= 2 else { return nil }
        
        struct PathNode {
            let text: String
            let score: Int
        }
        
        var dp: [PathNode?] = Array(repeating: nil, count: m + 1)
        dp[0] = PathNode(text: "", score: 0)
        
        for i in 0..<m {
            guard let cur = dp[i] else { continue }
            let maxSpan = min(6, m - i)
            
            for span in 1...maxSpan {
                let slice = tokens[i..<(i + span)]
                if span >= 2 {
                    // Check if all tokens in slice are complete, or if the last token in slice is incomplete
                    let allCompleteExceptMaybeLast = slice.dropLast().allSatisfy(\.isComplete)
                    guard allCompleteExceptMaybeLast else { continue }
                    
                    let lastTok = slice.last!
                    if lastTok.isComplete {
                        let key = slice.map(\.text).joined()
                        let word = UserLexicon.shared.preferredWords(for: key).first
                            ?? PinyinLexicon.builtinCorePhrases[key]?.first(where: { $0.count == span })
                            ?? PinyinLexicon.commonPhrases[key]?.first(where: { $0.count == span })
                            ?? PinyinLexicon.commonPhrases[key]?.first
                        if let matchedWord = word {
                            // Linear coverage score (span * 100) + multi-char cohesion bonus ((span - 1) * 15)
                            // Ensures two 2-syllable words (215 + 215 = 430) beat one 3-syllable + 1-orphan char (330 + 10 = 340)!
                            let isCore = (PinyinLexicon.builtinCorePhrases[key] != nil)
                            let stepScore = span * 100 + (span - 1) * 15 + (isCore ? 8 : 0)
                            let nextScore = cur.score + stepScore
                            if dp[i + span] == nil || nextScore > dp[i + span]!.score {
                                dp[i + span] = PathNode(text: cur.text + matchedWord, score: nextScore)
                            }
                        }
                    } else {
                        // Last token is an incomplete syllable prefix (e.g. "ni" + "h" -> "nihao" -> "你好")
                        let prefixKey = slice.dropLast().map(\.text).joined()
                        for expanded in expandPrefix(lastTok.text).prefix(8) {
                            let fullKey = prefixKey + expanded
                            if let matchedWord = PinyinLexicon.builtinCorePhrases[fullKey]?.first(where: { $0.count == span })
                                ?? PinyinLexicon.commonPhrases[fullKey]?.first(where: { $0.count == span }) {
                                let stepScore = span * 95 + (span - 1) * 12
                                let nextScore = cur.score + stepScore
                                if dp[i + span] == nil || nextScore > dp[i + span]!.score {
                                    dp[i + span] = PathNode(text: cur.text + matchedWord, score: nextScore)
                                }
                                break
                            }
                        }
                    }
                } else {
                    // Single syllable span (span == 1)
                    let tok = slice.first!
                    let s: String
                    if tok.isComplete {
                        s = tok.text
                    } else if let firstExpanded = expandPrefix(tok.text).first {
                        s = firstExpanded
                    } else {
                        continue
                    }
                    
                    let char = UserLexicon.shared.preferredWords(for: s).first(where: { $0.count == 1 })
                        ?? PinyinLexicon.sentenceSingleCharMap[s]
                        ?? PinyinLexicon.syllablesChars[s]?.first
                    if let c = char {
                        let nextScore = cur.score + 10
                        if dp[i + 1] == nil || nextScore > dp[i + 1]!.score {
                            dp[i + 1] = PathNode(text: cur.text + c, score: nextScore)
                        }
                    }
                }
            }
        }
        
        return dp[m]?.text
    }
    
    /// Queries candidate list for given raw pinyin buffer.
    public func query(rawInput: String) -> [Candidate] {
        let input = rawInput.lowercased().replacingOccurrences(of: "ü", with: "v").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !input.isEmpty else { return [] }
        
        let fullInputCount = input.count
        var seenWords = Set<String>()
        var candidates: [Candidate] = []
        
        func addCandidate(word: String, comment: String? = nil, consumedLength: Int = 0) {
            guard !word.isEmpty, !seenWords.contains(word) else { return }
            seenWords.insert(word)
            candidates.append(
                Candidate(
                    text: word,
                    comment: comment,
                    consumedInputLength: consumedLength == 0 ? fullInputCount : consumedLength
                )
            )
        }
        
        let stripped = input.replacingOccurrences(of: "'", with: "")
        let hasExplicitApostrophe = input.contains("'")
        
        // 0. User-learned / custom phrases highest priority
        for userWord in UserLexicon.shared.preferredWords(for: stripped) {
            addCandidate(word: userWord)
        }
        
        // 1. Direct match in high-frequency phrase lexicon
        // If user explicitly typed apostrophe (e.g. "xi'an"), prioritize multi-character words (like "西安") over single-char "xian" ("先")
        if hasExplicitApostrophe {
            if let phrases = PinyinLexicon.commonPhrases[input] {
                for word in phrases {
                    addCandidate(word: word)
                }
            }
            if let phrases = PinyinLexicon.commonPhrases[stripped] {
                for word in phrases where word.count >= 2 {
                    addCandidate(word: word)
                }
                for word in phrases {
                    addCandidate(word: word)
                }
            }
        } else {
            if let phrases = PinyinLexicon.commonPhrases[stripped] {
                for word in phrases {
                    addCandidate(word: word)
                }
            }
        }
        
        // 2. Jianpin (声母简拼 / 首字母缩写) for quick daily phrases (e.g. "nh" -> "你好", "zg" -> "中国", "srf" -> "输入法")
        if let abbrWords = PinyinLexicon.commonAbbreviations[stripped] {
            for w in abbrWords {
                addCandidate(word: w)
            }
        }
        
        // 3. Fuzzy Pinyin & Sogou-style Typo Auto-Correction (an<->ang, en<->eng, in<->ing, gn->ng, mg->ng, uen->un, iou->iu, uei->ui)
        if AetherSettings.shared.isFuzzyPinyinEnabled {
            var fuzzyKeys: [String] = []
            for (typo, corr) in [("gn", "ng"), ("mg", "ng"), ("uen", "un"), ("iou", "iu"), ("uei", "ui")] {
                if stripped.contains(typo) {
                    fuzzyKeys.append(stripped.replacingOccurrences(of: typo, with: corr))
                }
            }
            if stripped.contains("an") && !stripped.contains("ang") {
                fuzzyKeys.append(stripped.replacingOccurrences(of: "an", with: "ang"))
            } else if stripped.contains("ang") {
                fuzzyKeys.append(stripped.replacingOccurrences(of: "ang", with: "an"))
            }
            if stripped.contains("en") && !stripped.contains("eng") {
                fuzzyKeys.append(stripped.replacingOccurrences(of: "en", with: "eng"))
            } else if stripped.contains("eng") {
                fuzzyKeys.append(stripped.replacingOccurrences(of: "eng", with: "en"))
            }
            if stripped.contains("in") && !stripped.contains("ing") {
                fuzzyKeys.append(stripped.replacingOccurrences(of: "in", with: "ing"))
            } else if stripped.contains("ing") {
                fuzzyKeys.append(stripped.replacingOccurrences(of: "ing", with: "in"))
            }
            
            for fKey in fuzzyKeys {
                if let corePhrases = PinyinLexicon.builtinCorePhrases[fKey] {
                    for word in corePhrases {
                        addCandidate(word: word)
                    }
                }
                if let phrases = PinyinLexicon.commonPhrases[fKey] {
                    for word in phrases {
                        addCandidate(word: word)
                    }
                }
            }
        }
        
        // An exact syllable exposes its full character set regardless of segmentation.
        if !hasExplicitApostrophe, PinyinLexicon.initialExpansions[stripped] == nil,
           let characters = PinyinLexicon.syllablesChars[stripped] {
            for character in characters { addCandidate(word: character) }
        }

        // 4. Tokenize into syllables / prefixes and run sentence & phrase synthesis
        let tokens = segmentTokens(rawInput: input)
        if !tokens.isEmpty {
            let joined = tokens.map(\.text).joined()
            if let phrases = PinyinLexicon.commonPhrases[joined] {
                for word in phrases {
                    addCandidate(word: word)
                }
            }
            
            // 4a. If trailing token is an incomplete syllable/initial (e.g. "nih" -> ["ni", "h"], "zhongg" -> ["zhong", "g"]),
            // expand trailing prefix and match core phrases first, then general lexicon phrases!
            if tokens.count >= 2, let lastTok = tokens.last, !lastTok.isComplete {
                let prefixJoined = tokens.dropLast().map(\.text).joined()
                let expandedList = Array(expandPrefix(lastTok.text).prefix(10))
                for expanded in expandedList {
                    let candidateKey = prefixJoined + expanded
                    if let corePhrases = PinyinLexicon.builtinCorePhrases[candidateKey] {
                        for word in corePhrases {
                            addCandidate(word: word)
                        }
                    }
                }
                for expanded in expandedList {
                    let candidateKey = prefixJoined + expanded
                    if let phrases = PinyinLexicon.commonPhrases[candidateKey] {
                        for word in phrases.prefix(3) {
                            addCandidate(word: word)
                        }
                    }
                }
            }
            
            // 4b. Dynamic Programming full sentence composition (e.g. "woxiangchifan" -> "我想吃饭", "jintiantianqizenmeyang" -> "今天天气怎么样")
            if tokens.count >= 2 {
                if let composed = composeSentence(tokens: tokens) {
                    addCandidate(word: composed)
                }
            }
            
            // 4c. Single token (either complete syllable like "zhong" or initial/prefix like "n", "zh", "zho")
            if tokens.count == 1 {
                let tok = tokens[0]
                if tok.isComplete {
                    if let chars = PinyinLexicon.syllablesChars[tok.text] {
                        for c in chars {
                            addCandidate(word: c)
                        }
                    }
                    // Fuzzy single syllable characters
                    for fSyl in fuzzySyllableVariants(tok.text) {
                        if let chars = PinyinLexicon.syllablesChars[fSyl] {
                            for c in chars.prefix(4) {
                                addCandidate(word: c)
                            }
                        }
                    }
                } else {
                    // Incomplete prefix / single consonant (e.g. "n", "zh", "zho"):
                    // Show top characters and phrases from expanded syllables so Chinese candidates never vanish mid-typing!
                    let expandedSyllables = expandPrefix(tok.text)
                    for expSyl in expandedSyllables.prefix(6) {
                        if let chars = PinyinLexicon.syllablesChars[expSyl] {
                            for c in chars.prefix(3) {
                                addCandidate(word: c)
                            }
                        }
                    }
                }
            } else if tokens.count == 2 {
                // 2 tokens: check fuzzy 2-syllable phrase combinations & Cartesian character combinations
                let t1 = tokens[0]
                let t2 = tokens[1]
                let s1 = t1.isComplete ? t1.text : (expandPrefix(t1.text).first ?? t1.text)
                let s2 = t2.isComplete ? t2.text : (expandPrefix(t2.text).first ?? t2.text)
                
                // Check fuzzy 2-syllable phrases in lexicon
                if AetherSettings.shared.isFuzzyPinyinEnabled {
                    for f1 in [s1] + fuzzySyllableVariants(s1).prefix(2) {
                        for f2 in [s2] + fuzzySyllableVariants(s2).prefix(2) {
                            let fKey = f1 + f2
                            if fKey != joined, let phrases = PinyinLexicon.commonPhrases[fKey] {
                                for w in phrases.prefix(3) {
                                    addCandidate(word: w)
                                }
                            }
                        }
                    }
                }
                
                let chars1 = PinyinLexicon.syllablesChars[s1] ?? []
                let chars2 = PinyinLexicon.syllablesChars[s2] ?? []
                for c1 in chars1.prefix(4) {
                    for c2 in chars2.prefix(3) {
                        addCandidate(word: c1 + c2)
                    }
                }
            }
            
            // 4d. Partial prefix phrase candidates for multi-syllable input (e.g. "jintiantianqi" -> also offer "今天" with consumedLength = 6)
            if tokens.count >= 3 {
                for prefixCount in stride(from: min(3, tokens.count - 1), through: 2, by: -1) {
                    let prefixSlice = tokens[0..<prefixCount]
                    guard prefixSlice.allSatisfy(\.isComplete) else { continue }
                    let prefixKey = prefixSlice.map(\.text).joined()
                    let consumedLen = prefixSlice.last!.rawEndOffset
                    if let prefixPhrases = PinyinLexicon.commonPhrases[prefixKey] {
                        for w in prefixPhrases.prefix(2) {
                            addCandidate(word: w, consumedLength: consumedLen)
                        }
                    }
                }
            }
            
            // 4e. Single characters of the first syllable for step-by-step selection
            let firstTok = tokens[0]
            let firstSyl = firstTok.isComplete ? firstTok.text : (expandPrefix(firstTok.text).first ?? firstTok.text)
            let firstConsumed = firstTok.rawEndOffset
            if let firstSyllableChars = PinyinLexicon.syllablesChars[firstSyl] {
                for c in firstSyllableChars {
                    addCandidate(word: c, consumedLength: firstConsumed)
                }
            }
        }
        
        // Syllabic consonants such as ń must remain available without replacing
        // the normal initial-prefix behavior (n -> 你, m -> 们, etc.).
        if !hasExplicitApostrophe, PinyinLexicon.initialExpansions[stripped] != nil,
           let characters = PinyinLexicon.syllablesChars[stripped] {
            for character in characters { addCandidate(word: character) }
        }

        candidates = CandidateRanking.merge(text: candidates, input: input)

        // 5. English raw buffer fallback
        if !seenWords.contains(rawInput) {
            candidates.append(
                Candidate(
                    text: rawInput,
                    comment: "英",
                    consumedInputLength: fullInputCount
                )
            )
        }
        
        return candidates
    }
}
